CREATE OR REPLACE FUNCTION public.car_public_progress(_car_id uuid) RETURNS TABLE(job_id uuid,public_status text,completed_steps text[],message text,information_request text,updated_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.job_id,p.public_status,p.completed_steps,p.message,p.information_request,p.updated_at FROM public.job_progress p JOIN public.jobs j ON j.id=p.job_id JOIN public.cars c ON c.id=j.car_id WHERE c.id=_car_id AND (c.owner_id=auth.uid() OR public.is_editor(auth.uid())) ORDER BY p.updated_at DESC $$;
REVOKE ALL ON FUNCTION public.car_public_progress(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.car_public_progress(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.protect_car_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.id IS DISTINCT FROM OLD.id) THEN RAISE EXCEPTION 'Vehicle identity is immutable'; END IF; IF NEW.photo_path IS NOT NULL AND (NEW.photo_path NOT LIKE NEW.id::text||'/%' OR NEW.photo_path NOT LIKE '%.webp' OR position('..' in NEW.photo_path)>0) THEN RAISE EXCEPTION 'Invalid vehicle photo path'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_car_identity BEFORE INSERT OR UPDATE ON public.cars FOR EACH ROW EXECUTE FUNCTION public.protect_car_identity();